function ChatMessage({ message }: { message: SyntheciUIMessage }) {
  const citations = citationsForMessage(message);
  const text = messageText(message);
  const warnings = warningForMessage(message, citations, text);

  return (
    <div className="space-y-2">
      {message.role === "assistant" && citations.length > 0 ? (
        <Sources>
          <SourcesTrigger count={citations.length} />
          <SourcesContent>
            {citations.map((citation) => (
              <Source
                href={citation.sourceHref}
                key={`${message.id}-${citation.chunkId}`}
                target="_self"
                title={citation.fileName}
              >
