                <span className="text-slate-500">{citation.fileName}</span>
              </Source>
            ))}
          </SourcesContent>
        </Sources>
      ) : null}
      <Message from={message.role}>
        <MessageContent>
          {message.role === "assistant" ? (
            <CitedResponse citations={citations} text={text} />
          ) : (
            <p className="whitespace-pre-wrap">{text}</p>
          )}
        </MessageContent>
      </Message>
      {message.role === "assistant" && hasWarnings(warnings) ? (
        <div className="ml-0 flex items-center gap-2 text-xs text-amber-700">
          <AlertTriangle className="h-3.5 w-3.5" />
          {warningText(warnings)}
        </div>
      ) : null}
    </div>
  );
}

function CitedResponse({ citations, text }: { citations: Citation[]; text: string }) {
  if (citations.length === 0) {
    return <p className="whitespace-pre-wrap leading-7">{text || "Retrieving evidence..."}</p>;
  }

  const parts = text.split(/(\[\d+\])/g);
  return (
    <p className="whitespace-pre-wrap leading-7">
      {parts.map((part, index) => {
        const match = /^\[(\d+)\]$/.exec(part);
        if (!match) return <span key={`${part}-${index}`}>{part}</span>;
        const citation = citations.find((candidate) => candidate.rank === Number(match[1]));
        if (!citation) return <span key={`${part}-${index}`}>{part}</span>;
        return <CitationPill citation={citation} key={`${citation.chunkId}-${index}`} />;
      })}
    </p>
  );
}

function CitationPill({ citation }: { citation: Citation }) {
