async function refreshThreads(setThreads: (threads: ChatThreadSummary[]) => void) {
  const response = await fetch("/api/chat/threads");
  if (!response.ok) return;
  const payload = (await response.json()) as { threads: ChatThreadSummary[] };
  setThreads(payload.threads);
}

function latestCitations(messages: SyntheciUIMessage[]) {
  const assistant = [...messages].reverse().find((message) => message.role === "assistant");
  return assistant ? citationsForMessage(assistant) : [];
}

function citationsForMessage(message: SyntheciUIMessage) {
  const part = message.parts.find((candidate) => candidate.type === "data-citations");
  if (part?.type === "data-citations") return part.data.citations;
  return message.metadata?.citations ?? [];
}

function messageText(message: SyntheciUIMessage) {
  return message.parts
    .filter((part) => part.type === "text")
    .map((part) => part.text)
    .join("");
}

function warningForMessage(message: SyntheciUIMessage, citations: Citation[], text: string): CitationValidation {
  if (message.metadata?.citationWarnings) return message.metadata.citationWarnings;
  const usedLabels = [...new Set([...text.matchAll(/\[(\d+)\]/g)].map((match) => `[${match[1]}]`))];
  const validLabels = new Set(citations.map((citation) => `[${citation.rank}]`));
  return {
    usedLabels,
    invalidLabels: usedLabels.filter((label) => !validLabels.has(label)),
    missingCitation: citations.length > 0 && text.trim().length > 80 && usedLabels.length === 0,
  };
}

function hasWarnings(warnings: CitationValidation) {
  return warnings.invalidLabels.length > 0 || warnings.missingCitation;
}

function warningText(warnings: CitationValidation) {
  if (warnings.invalidLabels.length > 0) {
    return `Answer referenced unavailable citation ${warnings.invalidLabels.join(", ")}.`;
  }
  return "Answer has retrieved evidence but no inline citation markers.";
}

function formatDate(value: string) {
  return new Intl.DateTimeFormat("en", {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(new Date(value));
}

function formatSourceType(value: string) {
  return value.replace(/[._/-]+/g, " ").replace(/\b\w/g, (letter) => letter.toUpperCase());
}

