const THINK_OPEN = "<think>";
const THINK_CLOSE = "</think>";

export interface ThinkingTextFilterState {
  buffer: string;
  inThinkingBlock: boolean;
}

export function createThinkingTextFilterState(): ThinkingTextFilterState {
  return {
    buffer: "",
    inThinkingBlock: false,
  };
}

export function stripThinkingText(input: string) {
  const state = createThinkingTextFilterState();
  return filterThinkingTextDelta(state, input, true);
}

export function filterThinkingTextDelta(state: ThinkingTextFilterState, delta: string, flush = false) {
  state.buffer += delta;
  let output = "";

  while (state.buffer.length > 0) {
    const lowerBuffer = state.buffer.toLowerCase();

    if (state.inThinkingBlock) {
      const closeIndex = lowerBuffer.indexOf(THINK_CLOSE);
      if (closeIndex === -1) {
        const keepLength = flush ? 0 : suffixPrefixLength(lowerBuffer, THINK_CLOSE);
        state.buffer = keepLength > 0 ? state.buffer.slice(-keepLength) : "";
        break;
      }

      state.buffer = state.buffer.slice(closeIndex + THINK_CLOSE.length);
      state.inThinkingBlock = false;
      continue;
    }

    const openIndex = lowerBuffer.indexOf(THINK_OPEN);
    if (openIndex === -1) {
      const keepLength = flush ? 0 : suffixPrefixLength(lowerBuffer, THINK_OPEN);
      const emitLength = state.buffer.length - keepLength;
      output += state.buffer.slice(0, emitLength);
      state.buffer = keepLength > 0 ? state.buffer.slice(-keepLength) : "";
      break;
    }

    output += state.buffer.slice(0, openIndex);
    state.buffer = state.buffer.slice(openIndex + THINK_OPEN.length);
    state.inThinkingBlock = true;
  }

  if (flush) {
    state.buffer = "";
    state.inThinkingBlock = false;
  }

  return output;
}

function suffixPrefixLength(value: string, token: string) {
  const maxLength = Math.min(value.length, token.length - 1);
  for (let length = maxLength; length > 0; length -= 1) {
    if (token.startsWith(value.slice(-length))) return length;
  }
  return 0;
}

