    model: groq(env.AI_CHAT_MODEL),
    middleware: extractReasoningMiddleware({ tagName: "think" }),
  });
}

export function embeddingModel() {
  const env = getServerEnv();
  return google.embedding(env.AI_EMBEDDING_MODEL);
