    metadataScore: Math.max(left.metadataScore ?? 0, right.metadataScore ?? 0),
    vectorDistance: Math.min(left.vectorDistance ?? Number.POSITIVE_INFINITY, right.vectorDistance ?? Number.POSITIVE_INFINITY),
